namespace UniversityCourseCatalog.Models;

public class Department
{
    public string Id { get; set; } = "";
    public string Name { get; set; } = "";
    public string Description { get; set; } = "";
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public string Id { get; set; } = "";
    public string DepartmentId { get; set; } = "";
    public string Code { get; set; } = "";
    public string Title { get; set; } = "";
    public string Description { get; set; } = "";
    public int Credits { get; set; }
    public string Schedule { get; set; } = "";
    public string InstructorName { get; set; } = "";
    public string InstructorBio { get; set; } = "";
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100, ErrorMessage = "Name cannot exceed 100 characters.")]
    public string StudentName { get; set; } = "";

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9\-]+$", ErrorMessage = "Student ID must contain only letters, numbers, and hyphens.")]
    public string StudentId { get; set; } = "";

    [Required(ErrorMessage = "Please select a course.")]
    public string CourseId { get; set; } = "";
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Id = "cs", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
        new() { Id = "math", Name = "Mathematics", Description = "Exploration of abstract structures, quantities, and patterns." },
        new() { Id = "eng", Name = "English", Description = "Literature, writing, and language studies." },
        new() { Id = "phys", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
        new() { Id = "hist", Name = "History", Description = "Examination of past events and civilizations." },
        new() { Id = "bio", Name = "Biology", Description = "Study of living organisms and life processes." },
    ];

    private readonly List<Course> _courses =
    [
        // Computer Science
        new()
        {
            Id = "cs101", DepartmentId = "cs", Code = "CS 101", Title = "Introduction to Programming",
            Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures. No prior experience required.",
            Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", IsFeatured = true,
            InstructorName = "Dr. Sarah Chen",
            InstructorBio = "Dr. Chen holds a Ph.D. in Computer Science from MIT and has 15 years of teaching experience. Her research focuses on programming language design and CS education."
        },
        new()
        {
            Id = "cs201", DepartmentId = "cs", Code = "CS 201", Title = "Data Structures and Algorithms",
            Description = "Study of fundamental data structures (lists, trees, graphs, hash tables) and algorithm design techniques (divide-and-conquer, dynamic programming, greedy algorithms).",
            Credits = 4, Schedule = "Tue/Thu 10:30 AM–12:00 PM",
            InstructorName = "Dr. James Okafor",
            InstructorBio = "Dr. Okafor specializes in algorithm optimization and computational complexity. He previously worked at Google Research before joining academia."
        },
        new()
        {
            Id = "cs310", DepartmentId = "cs", Code = "CS 310", Title = "Database Systems",
            Description = "Principles of database design, relational algebra, SQL, normalization, transaction processing, and an introduction to NoSQL databases.",
            Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM",
            InstructorName = "Prof. Maria Gonzalez",
            InstructorBio = "Prof. Gonzalez has extensive industry experience in data engineering at Amazon and Oracle. She brings practical insights to database theory."
        },

        // Mathematics
        new()
        {
            Id = "math101", DepartmentId = "math", Code = "MATH 101", Title = "Calculus I",
            Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering problems.",
            Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", IsFeatured = true,
            InstructorName = "Dr. Robert Kim",
            InstructorBio = "Dr. Kim is a recipient of the National Teaching Excellence Award. He has published over 40 papers in applied mathematics."
        },
        new()
        {
            Id = "math250", DepartmentId = "math", Code = "MATH 250", Title = "Linear Algebra",
            Description = "Vector spaces, matrices, linear transformations, eigenvalues, and applications to data science and engineering.",
            Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM",
            InstructorName = "Dr. Emily Zhang",
            InstructorBio = "Dr. Zhang's research bridges pure mathematics and machine learning. She co-developed the university's data science minor."
        },

        // English
        new()
        {
            Id = "eng101", DepartmentId = "eng", Code = "ENG 101", Title = "Expository Writing",
            Description = "Develop clear, effective writing skills through essays, research papers, and peer review. Emphasis on argumentation and critical thinking.",
            Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", IsFeatured = true,
            InstructorName = "Prof. David Oconnor",
            InstructorBio = "Prof. O'Connor is a published author and former journalist. He has taught writing at the university level for over 20 years."
        },
        new()
        {
            Id = "eng220", DepartmentId = "eng", Code = "ENG 220", Title = "American Literature",
            Description = "Survey of major American literary works from the colonial period to the present. Explores themes of identity, democracy, and social change.",
            Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM",
            InstructorName = "Dr. Lisa Park",
            InstructorBio = "Dr. Park specializes in 20th-century American fiction and has authored two books on modernist literature."
        },

        // Physics
        new()
        {
            Id = "phys101", DepartmentId = "phys", Code = "PHYS 101", Title = "General Physics I",
            Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions with hands-on experiments.",
            Credits = 4, Schedule = "Tue/Thu 10:00–11:30 AM + Fri Lab 2:00–4:00 PM",
            InstructorName = "Dr. Alan Patel",
            InstructorBio = "Dr. Patel is an experimental physicist whose work on quantum optics has been published in Nature and Physical Review Letters."
        },

        // History
        new()
        {
            Id = "hist101", DepartmentId = "hist", Code = "HIST 101", Title = "World History to 1500",
            Description = "Survey of world civilizations from ancient Mesopotamia through the late medieval period. Examines political, social, and cultural developments.",
            Credits = 3, Schedule = "Mon/Wed 3:30–4:45 PM",
            InstructorName = "Dr. Catherine Williams",
            InstructorBio = "Dr. Williams is an expert in medieval European history and has conducted archaeological research across the Mediterranean."
        },

        // Biology
        new()
        {
            Id = "bio101", DepartmentId = "bio", Code = "BIO 101", Title = "Introduction to Biology",
            Description = "Fundamentals of cell biology, genetics, evolution, and ecology. Includes laboratory component with microscopy and dissection.",
            Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Thu Lab 3:00–5:00 PM", IsFeatured = true,
            InstructorName = "Dr. Michael Torres",
            InstructorBio = "Dr. Torres is a molecular biologist with active research in gene expression. He received the University Distinguished Teaching Award in 2024."
        },
    ];

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(string id) =>
        _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? departmentId = null, string? searchTerm = null)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(departmentId))
        {
            query = query.Where(c => c.DepartmentId.Equals(departmentId, StringComparison.OrdinalIgnoreCase));
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            query = query.Where(c =>
                c.Title.Contains(searchTerm, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(searchTerm, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(searchTerm, StringComparison.OrdinalIgnoreCase));
        }

