@page "/courses"
@inject CatalogService Catalog

<PageTitle>Course Catalog</PageTitle>

<h1 class="mb-4">Course Catalog</h1>

<form method="get" action="courses" class="row g-3 mb-4" data-enhance>
    <div class="col-md-6">
        <label for="search" class="form-label">Search</label>
        <input type="text" class="form-control" id="search" name="search" value="@Search" placeholder="Search by title, code, or keyword..." />
    </div>
    <div class="col-md-4">
        <label for="department" class="form-label">Department</label>
        <select class="form-select" id="department" name="department">
            <option value="">All Departments</option>
            @foreach (var dept in _departments)
            {
                <option value="@dept.Id" selected="@(Department == dept.Id)">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-2 d-flex align-items-end">
        <button type="submit" class="btn btn-primary w-100">Filter</button>
    </div>
</form>

@if (Department is not null)
{
    var dept = Catalog.GetDepartment(Department);
    if (dept is not null)
    {
        <div class="alert alert-info d-flex justify-content-between align-items-center">
            <span>Showing courses in <strong>@dept.Name</strong></span>
            <a href="courses@(Search is not null ? $"?search={Search}" : "")" class="btn btn-sm btn-outline-info">Clear Filter</a>
        </div>
    }
}

@if (_courses.Count == 0)
{
    <div class="alert alert-warning">
        No courses found matching your criteria. Try adjusting your search or filter.
    </div>
}
else
{
    <div class="table-responsive">
        <table class="table table-hover align-middle">
            <thead class="table-light">
                <tr>
                    <th>Code</th>
                    <th>Title</th>
                    <th>Department</th>
                    <th>Credits</th>
                    <th>Schedule</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in _courses)
                {
                    var dept = Catalog.GetDepartment(course.DepartmentId);
                    <tr>
                        <td><strong>@course.Code</strong></td>
                        <td>@course.Title</td>
                        <td>@dept?.Name</td>
                        <td>@course.Credits</td>
                        <td class="text-muted small">@course.Schedule</td>
                        <td><a href="courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
    <p class="text-muted">@_courses.Count course(s) found</p>
}

@code {
    [SupplyParameterFromQuery] public string? Search { get; set; }
    [SupplyParameterFromQuery] public string? Department { get; set; }

    private List<Course> _courses = [];
    private List<Department> _departments = [];

    protected override void OnInitialized()
    {
        _departments = Catalog.GetDepartments();
        _courses = Catalog.GetCourses(Department, Search);
    }
}

@page "/courses/{CourseId}"
@inject CatalogService Catalog

@if (_course is null)
{
    <PageTitle>Course Not Found</PageTitle>
    <div class="alert alert-danger">
        <h4>Course Not Found</h4>
        <p>The requested course could not be found. <a href="courses">Return to catalog</a>.</p>
    </div>
}
else
{
    <PageTitle>@_course.Code – @_course.Title</PageTitle>

    <nav aria-label="breadcrumb" class="mb-3">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="courses?department=@_course.DepartmentId">@_department?.Name</a></li>
            <li class="breadcrumb-item active" aria-current="page">@_course.Code</li>
        </ol>
    </nav>

    <div class="row">
        <div class="col-lg-8">
            <h1 class="mb-1">@_course.Code: @_course.Title</h1>
            <p class="text-muted mb-4">@_department?.Name</p>

            <section class="mb-4">
                <h2 class="h5">Description</h2>
                <p>@_course.Description</p>
            </section>

            <section class="mb-4">
                <h2 class="h5">Instructor</h2>
                <p class="fw-semibold mb-1">@_course.InstructorName</p>
                <p class="text-muted">@_course.InstructorBio</p>
            </section>
        </div>

        <div class="col-lg-4">
            <div class="card shadow-sm">
                <div class="card-body">
                    <h5 class="card-title">Course Details</h5>
                    <ul class="list-unstyled mb-0">
                        <li class="mb-2"><strong>Credits:</strong> @_course.Credits</li>
                        <li class="mb-2"><strong>Schedule:</strong> @_course.Schedule</li>
                        <li class="mb-2"><strong>Course Code:</strong> @_course.Code</li>
                    </ul>
                </div>
                <div class="card-footer">
                    <a href="enroll?courseId=@_course.Id" class="btn btn-primary w-100">Request Enrollment</a>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public string CourseId { get; set; } = "";

    private Course? _course;
    private Department? _department;

    protected override void OnInitialized()
    {
        _course = Catalog.GetCourse(CourseId);
        if (_course is not null)
        {
            _department = Catalog.GetDepartment(_course.DepartmentId);
        }
    }
}

@page "/enroll"
@inject CatalogService Catalog

<PageTitle>Enrollment Request</PageTitle>

<h1 class="mb-4">Enrollment Request</h1>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Thank you, <strong>@_model.StudentName</strong>. Your enrollment request for
            <strong>@(_selectedCourse?.Code) – @(_selectedCourse?.Title)</strong>
            has been received.</p>
        <p class="mb-0">You will receive a confirmation at your university email. <a href="courses">Browse more courses</a>.</p>
    </div>
}
else
{
    <div class="row">
        <div class="col-lg-8">
            <p class="text-muted mb-4">Fill out the form below to request enrollment in a course. All fields are required.</p>

            <EditForm method="post" Model="_model" OnValidSubmit="HandleSubmit" FormName="enrollment" Enhance>
                <DataAnnotationsValidator />
                <AntiforgeryToken />

                <div class="mb-3">
                    <label for="studentName" class="form-label">Full Name</label>
                    <InputText id="studentName" class="form-control" @bind-Value="_model.StudentName" />
                    <ValidationMessage For="() => _model.StudentName" />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID</label>
                    <InputText id="studentId" class="form-control" @bind-Value="_model.StudentId" placeholder="e.g. STU-12345" />
                    <ValidationMessage For="() => _model.StudentId" />
                </div>

                <div class="mb-3">
                    <label for="courseId" class="form-label">Course</label>
                    <InputSelect id="courseId" class="form-select" @bind-Value="_model.CourseId">
                        <option value="">— Select a course —</option>
                        @foreach (var course in _courses)
                        {
                            <option value="@course.Id">@course.Code – @course.Title (@course.Credits cr.)</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => _model.CourseId" />
                </div>

                <button type="submit" class="btn btn-primary">Submit Request</button>
                <a href="courses" class="btn btn-outline-secondary ms-2">Cancel</a>
            </EditForm>
        </div>
    </div>
}

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest _model { get; set; } = new();

    [SupplyParameterFromQuery(Name = "courseId")]
    public string? PreselectedCourseId { get; set; }

    private List<Course> _courses = [];
    private Course? _selectedCourse;
    private bool _submitted;

    protected override void OnInitialized()
    {
        _courses = Catalog.GetCourses();

        if (!string.IsNullOrEmpty(PreselectedCourseId) && string.IsNullOrEmpty(_model.CourseId))
        {
            _model.CourseId = PreselectedCourseId;
        }
    }

    private void HandleSubmit()
    {
        _selectedCourse = Catalog.GetCourse(_model.CourseId);
        _submitted = true;
    }
}

